<?php
require_once __DIR__.'/includes/auth.php';require_roles(['ADMIN','ORGANIZADOR']);require_once __DIR__.'/includes/helpers.php';$pageTitle='Resultados y KDA';
try{$torneos=option_map('torneos');$arbitros=option_map('arbitros');$jugadores=option_map('jugadores');$selected=$_GET['torneo']??($_POST['torneo_contexto']??array_key_first($torneos));$partidas=$selected?oracle_cursor('AV_JP_RM_BE_SP_PARTIDA_LISTAR',['P_ID_TORNEO'=>$selected]):[];
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(isset($_POST['resultado'])){oracle_run('BEGIN AV_JP_RM_BE_SP_REGISTRAR_RESULTADO(:P_ID_PARTIDA,:P_ID_ARBITRO,:P_PUNTAJE_LOCAL,:P_PUNTAJE_VISITA); END;',['P_ID_PARTIDA'=>$_POST['partida'],'P_ID_ARBITRO'=>$_POST['arbitro'],'P_PUNTAJE_LOCAL'=>$_POST['local'],'P_PUNTAJE_VISITA'=>$_POST['visita']]);flash('success','Resultado registrado; el trigger de auditoría se ejecuta si cambia el marcador.');}
 if(isset($_POST['kda'])){oracle_run('BEGIN AV_JP_RM_BE_SP_REGISTRAR_KDA(:P_ID_PARTIDA,:P_ID_JUGADOR,:P_KILLS,:P_DEATHS,:P_ASSISTS,:P_ES_MVP); END;',['P_ID_PARTIDA'=>$_POST['partida'],'P_ID_JUGADOR'=>$_POST['jugador'],'P_KILLS'=>$_POST['kills'],'P_DEATHS'=>$_POST['deaths'],'P_ASSISTS'=>$_POST['assists'],'P_ES_MVP'=>$_POST['mvp']]);flash('success','KDA registrado correctamente.');}
 header('Location: gestor_resultados.php?torneo='.urlencode($_POST['torneo_contexto']));exit;}}
catch(Throwable $e){$error=$e->getMessage();}
include __DIR__.'/includes/header.php';function selopts($a){foreach($a as $v=>$l)echo '<option value="'.h($v).'">'.h($l).'</option>';}?>
<main class="content"><div class="page-head"><div><h1>🎯 Resultados y KDA</h1><p>Gestor 4: registra marcadores, puntajes del torneo y rendimiento individual.</p></div></div><?php if(!empty($error)):?><div class="callout" style="border-color:#ff667d"><?=h($error)?></div><?php endif;?><form method="get" class="panel" style="margin-bottom:16px"><div class="field"><label>Torneo de trabajo</label><select name="torneo" onchange="this.form.submit()"><?php foreach($torneos??[] as $v=>$l):?><option value="<?=h($v)?>" <?=((string)$v===(string)$selected)?'selected':''?>><?=h($l)?></option><?php endforeach;?></select></div></form><div class="grid grid-2"><section class="panel"><h2 class="section-title">Registrar resultado</h2><form method="post"><input type="hidden" name="resultado" value="1"><input type="hidden" name="torneo_contexto" value="<?=h($selected)?>"><div class="field"><label>Partida *</label><select name="partida" required><?php foreach($partidas??[] as $p):?><option value="<?=h($p['ID_PARTIDA'])?>">#<?=h($p['ID_PARTIDA'].' · '.$p['EQUIPO_LOCAL'].' vs '.($p['EQUIPO_VISITA']?:'BYE'))?></option><?php endforeach;?></select></div><div class="field"><label>Árbitro *</label><select name="arbitro" required><?php selopts($arbitros??[])?></select></div><div class="grid grid-2"><div class="field"><label>Puntaje local *</label><input type="number" min="0" name="local" required></div><div class="field"><label>Puntaje visita *</label><input type="number" min="0" name="visita" required></div></div><div class="form-actions"><button class="btn">Registrar resultado</button></div></form></section><section class="panel"><h2 class="section-title">Registrar KDA</h2><form method="post"><input type="hidden" name="kda" value="1"><input type="hidden" name="torneo_contexto" value="<?=h($selected)?>"><div class="field"><label>Partida *</label><select name="partida" required><?php foreach($partidas??[] as $p):?><option value="<?=h($p['ID_PARTIDA'])?>">#<?=h($p['ID_PARTIDA'].' · '.$p['EQUIPO_LOCAL'].' vs '.($p['EQUIPO_VISITA']?:'BYE'))?></option><?php endforeach;?></select></div><div class="field"><label>Jugador *</label><select name="jugador" required><?php selopts($jugadores??[])?></select></div><div class="grid grid-3"><div class="field"><label>Kills</label><input type="number" min="0" name="kills" value="0"></div><div class="field"><label>Deaths</label><input type="number" min="0" name="deaths" value="0"></div><div class="field"><label>Assists</label><input type="number" min="0" name="assists" value="0"></div></div><div class="field"><label>MVP</label><select name="mvp"><option value="N">No</option><option value="S">Sí</option></select></div><div class="form-actions"><button class="btn">Guardar KDA</button></div></form></section></div><section class="panel" style="margin-top:16px"><h2 class="section-title">Partidas del torneo</h2><div class="table-wrap"><table><thead><tr><th>ID</th><th>Local</th><th>Visita</th><th>Marcador</th><th>Estado</th></tr></thead><tbody><?php foreach($partidas??[] as $p):?><tr><td><?=h($p['ID_PARTIDA'])?></td><td><?=h($p['EQUIPO_LOCAL'])?></td><td><?=h($p['EQUIPO_VISITA']?:'BYE')?></td><td><?=h(($p['PUNTAJE_LOCAL']??'-').' - '.($p['PUNTAJE_VISITA']??'-'))?></td><td><?=h($p['ESTADO'])?></td></tr><?php endforeach;?></tbody></table></div></section></main><?php include __DIR__.'/includes/footer.php';?>
